import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error in your code: {e}')

# Check for pandas import
found_pandas = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'pandas' for name in node.names):
        found_pandas = True
    if isinstance(node, ast.ImportFrom) and node.module == 'pandas':
        found_pandas = True

if not found_pandas:
    raise AssertionError('Task 1: Missing import pandas (check syntax)')

# Check for pd.Series() call
found_series = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Attribute):
            if isinstance(node.func.value, ast.Name) and node.func.value.id == 'pd' and node.func.attr == 'Series':
                found_series = True

if not found_series:
    raise AssertionError('Task 2: Missing pd.Series() call')

# Check for label-based access (dictionary-style indexing)
found_label_access = False
for node in ast.walk(tree):
    if isinstance(node, ast.Subscript):
        if isinstance(node.slice, ast.Constant) and node.slice.value == 'Monitor':
            found_label_access = True
        elif isinstance(node.slice, ast.Str) and node.slice.s == 'Monitor':  # For older Python versions
            found_label_access = True

if not found_label_access:
    raise AssertionError('Task 4: Missing label-based access with product_series[\'Monitor\']')

# Check for print statements (at least 2)
print_calls = [node for node in ast.walk(tree) if isinstance(node, ast.Call) and 
               isinstance(node.func, ast.Name) and node.func.id == 'print']

if len(print_calls) < 2:
    raise AssertionError('Tasks 3 & 5: Expected at least 2 print statements')

print('TEST_PASSED')
